import numpy as np
from collections import Counter, deque
def f(g_):
    g_=np.array(g_); H,W=g_.shape
    bg=Counter(g_.flat).most_common(1)[0][0]
    seen=np.zeros_like(g_,bool)
    res=[[bg]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if g_[i,j]!=bg and not seen[i,j]:
                q=deque([(i,j)]); seen[i,j]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g_[x,y]!=bg and not seen[x,y]:
                            seen[x,y]=True; q.append((x,y))
                rs=[a for a,b in cells]; cs=[b for a,b in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                m=[[int(g_[r,c]) for c in range(c0,c1+1)] for r in range(r0,r1+1)]
                wid=c1-c0+1
                for ri in range(len(m)):
                    for ci in range(wid):
                        val=m[ri][wid-1-ci]
                        rr,cc=r0+ri,c1-ci
                        res[rr][cc]=val
    return res
